 "content": "def transform(grid):
    """Move each nonzero cell left by its distance in rows above the final occupied row."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    occupied_rows = [r for r, row in enumerate(grid) if any(value != 0 for value in row)]
    if not occupied_rows:
        return [row[:] for row in grid]
    baseline = max(occupied_rows)
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r, row in enumerate(grid):
        shift = max(0, baseline - r)
        for c, value in enumerate(row):
            if value != 0:
                nc = c - shift
                if 0 <= nc < w:
                    out[r][nc] = value
    return out
